 "content": "def transform(grid):
    """Extend each bottom-row 5 marker upward through its column.

    Existing nonzero cells in a marked column are color transitions: the
    current color propagates upward through zeros until the next clue.
    """
    out = [row[:] for row in grid]
    if not out:
        return out
    h = len(out)
    for c, marker in enumerate(out[-1]):
        if marker != 5:
            continue
        color = marker
        for r in range(h - 1, -1, -1):
            if out[r][c] != 0:
                color = out[r][c]
            else:
                out[r][c] = color
    return out

if __name__ == "__main__":
    import json, sys
